UPDATE crm_order SET refunded_fen=refunded_fen+#{amountFen},version=version+1
WHERE tenant_id=#{tenantId} AND id=#{id} AND version=#{expectedVersion}
  AND #{amountFen} > 0 AND refunded_fen+#{amountFen} <= paid_fen

mapper.select:
SELECT  FROM crm_order o INNER JOIN crm_customer c ON c.tenant_id=o.tenant_id AND c.id=o.customer_id AND c.deleted=0
WHERE o.tenant_id=#{tenantId}

AND o.customer_id=#{customerId}
AND o.status=#{status}
ORDER BY o.id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM crm_order o INNER JOIN crm_customer c ON c.tenant_id=o.tenant_id AND c.id=o.customer_id AND c.deleted=0
WHERE o.tenant_id=#{tenantId}

AND o.customer_id=#{customerId}
AND o.status=#{status}

SELECT  FROM crm_entitlement e INNER JOIN crm_project p ON p.tenant_id=e.tenant_id AND p.id=e.project_id
WHERE e.tenant_id=#{tenantId}
AND 1=0
AND e.order_item_id IN #{itemId}
ORDER BY e.id

SELECT  FROM crm_entitlement e
INNER JOIN crm_project p ON p.tenant_id=e.tenant_id AND p.id=e.project_id
INNER JOIN crm_customer c ON c.tenant_id=e.tenant_id AND c.id=e.customer_id AND c.deleted=0
WHERE e.tenant_id=#{tenantId}

AND e.customer_id=#{customerId}
AND e.status=#{status}
ORDER BY e.id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM crm_entitlement e INNER JOIN crm_customer c ON c.tenant_id=e.tenant_id AND c.id=e.customer_id AND c.deleted=0
WHERE e.tenant_id=#{tenantId}

AND e.customer_id=#{customerId}
AND e.status=#{status}

