UPDATE crm_outbox_event
SET status='SENT',sent_at=#{sentAt},last_error=NULL,next_retry_at=NULL,
  claim_owner=NULL,claim_expires_at=NULL,version=version+1
WHERE tenant_id=#{tenantId} AND id=#{id} AND version=#{expectedVersion}
  AND status='CLAIMED' AND claim_owner=#{claimOwner}

UPDATE crm_outbox_event
SET status='FAILED',retry_count=retry_count+1,last_error=#{error},next_retry_at=#{nextRetryAt},
  claim_owner=NULL,claim_expires_at=NULL,version=version+1
WHERE tenant_id=#{tenantId} AND id=#{id} AND version=#{expectedVersion}
  AND status='CLAIMED' AND claim_owner=#{claimOwner}
